"""
PCSX2 CoverSync
A cross-platform (Linux/Windows) utility tailored for the PCSX2 emulator.
"""

import json
import os
import re
import shlex
import shutil
import subprocess
import threading
import time
import urllib.error
import urllib.request
import base64
import io
from typing import Dict, List, Optional, Callable

import tkinter as tk
from tkinter import filedialog, messagebox, ttk

from PIL import Image, ImageTk

try:
    import PIL._tkinter_finder
except ImportError:
    pass

# =====================================================================
LOGO_B64 = """

"""
# =====================================================================

CONFIG_FILE = "config_launcher.json"
SERIAL_PATTERN = re.compile(
    r'(SLUS|SLES|SCUS|SCES|SLPM|SLPS|SLAJ|SLJS|KOEI|SCCS)[\s_.\-]*(\d{3})[\s_.\-]*(\d{2})',
    re.IGNORECASE
)
URL_MAP = {
    "default": "https://raw.githubusercontent.com/xlenore/ps2-covers/main/covers/default/{serial}.jpg",
    "3d": "https://raw.githubusercontent.com/xlenore/ps2-covers/main/covers/3d/{serial}.png"
}

COLOR_BG_MAIN = "#1e1e1e"
COLOR_BG_CARD = "#2d2d2d"
COLOR_BG_INPUT = "#242424"
COLOR_TXT_MAIN = "#ffffff"
COLOR_TXT_MUTED = "#9a9a9a"
COLOR_ACCENT_BLUE = "#3584e4"
COLOR_ACCENT_GREEN = "#26a269"
COLOR_BG_HOVER = "#383838"


def detect_environment_paths() -> Dict[str, str]:
    home_dir = os.path.expanduser("~")
    paths = {"covers_dir": "", "pcsx2_executable": "", "games_dir": ""}

    if os.name == 'posix':
        cover_routes = [
            os.path.join(home_dir, ".var/app/net.pcsx2.PCSX2/config/PCSX2/covers"),
            os.path.join(home_dir, ".config/PCSX2/covers")
        ]
        for route in cover_routes:
            if os.path.exists(route):
                paths["covers_dir"] = route
                break

        if not paths["covers_dir"]:
            gear_lever_route = os.path.join(home_dir, ".config/PCSX2/covers")
            if os.path.exists(gear_lever_route):
                paths["covers_dir"] = gear_lever_route

        for bin_name in ["pcsx2-qt", "pcsx2", "PCSX2"]:
            found_path = shutil.which(bin_name)
            if found_path:
                paths["pcsx2_executable"] = found_path
                break

        if not paths["pcsx2_executable"]:
            flatpak_routes = [
                os.path.join(home_dir, ".local/share/flatpak/exports/bin/net.pcsx2.PCSX2"),
                "/var/lib/flatpak/exports/bin/net.pcsx2.PCSX2"
            ]
            for route in flatpak_routes:
                if os.path.exists(route):
                    paths["pcsx2_executable"] = "flatpak run net.pcsx2.PCSX2"
                    break

        if not paths["pcsx2_executable"]:
            appimage_containers = [
                os.path.join(home_dir, "AppImages"),
                os.path.join(home_dir, "Applications"),
                os.path.join(home_dir, ".local/share/Applications")
            ]
            for folder in appimage_containers:
                if os.path.exists(folder):
                    for file in os.listdir(folder):
                        if file.lower().startswith("pcsx2") and file.lower().endswith(".appimage"):
                            paths["pcsx2_executable"] = os.path.join(folder, file)
                            break
                if paths["pcsx2_executable"]:
                    break

        game_routes = [
            os.path.join(home_dir, "Games/PS2"),
            os.path.join(home_dir, "Jogos/PS2"),
            os.path.join(home_dir, "Roms/ps2")
        ]
        for route in game_routes:
            if os.path.exists(route):
                paths["games_dir"] = route
                break

    else:
        user_profile = os.environ.get("USERPROFILE", "")
        cover_routes = [
            os.path.join(user_profile, "Documents", "PCSX2", "covers"),
            os.path.join(user_profile, "OneDrive", "Documentos", "PCSX2", "covers"),
            os.path.join(os.environ.get("APPDATA", ""), "PCSX2", "covers")
        ]
        for route in cover_routes:
            if os.path.exists(route):
                paths["covers_dir"] = route
                break

        executable_routes = [
            r"C:\Program Files\PCSX2\pcsx2-qt.exe",
            r"C:\Program Files (x86)\PCSX2\pcsx2-qt.exe"
        ]
        for route in executable_routes:
            if os.path.exists(route):
                paths["pcsx2_executable"] = route
                break

    return paths


def load_local_configuration() -> Optional[Dict[str, str]]:
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, 'r', encoding='utf-8') as file:
                return json.load(file)
        except json.JSONDecodeError:
            return None
    return None


def save_local_configuration(config_data: Dict[str, str]) -> None:
    with open(CONFIG_FILE, 'w', encoding='utf-8') as file:
        json.dump(config_data, file, indent=4, ensure_ascii=False)


def extract_game_serial(file_path: str) -> Optional[str]:
    file_name = os.path.basename(file_path)
    match = SERIAL_PATTERN.search(file_name)
    if match:
        return f"{match.group(1).upper()}-{match.group(2)}{match.group(3)}"

    if file_name.lower().endswith('.iso'):
        try:
            with open(file_path, 'rb') as file:
                buffer = file.read(10 * 1024 * 1024)
                text_segment = buffer.decode('utf-8', errors='ignore')
                match = SERIAL_PATTERN.search(text_segment)
                if match:
                    return f"{match.group(1).upper()}-{match.group(2)}{match.group(3)}"
        except IOError:
            pass
    return None


def scan_game_directory(games_dir: str) -> List[str]:
    valid_extensions = ('.iso', '.chd', '.cso', '.bin', '.gz')
    matched_files = []
    for root, _, files in os.walk(games_dir):
        for file in files:
            if file.lower().endswith(valid_extensions):
                matched_files.append(os.path.join(root, file))
    return matched_files


def synchronize_assets(config: Dict[str, str], progress_hook: Callable[[int, str], None], stop_signal: threading.Event) -> bool:
    games_dir = config["pasta_jogos"]
    covers_dir = config["pasta_covers"]
    cover_style = config.get("tipo_capa", "3d")
    extension = "jpg" if cover_style == "default" else "png"

    if not os.path.exists(covers_dir):
        os.makedirs(covers_dir)

    for remaining_seconds in range(3, 0, -1):
        if stop_signal.is_set():
            return False
        progress_hook(0, f"Iniciando automático em {remaining_seconds}s... Clique em Ajustes para alterar.")
        time.sleep(1.0)

    if stop_signal.is_set():
        return False

    progress_hook(0, "Escaneando biblioteca de jogos...")
    game_files = scan_game_directory(games_dir)
    total_games = len(game_files)

    if total_games == 0:
        progress_hook(100, "Nenhum jogo encontrado na pasta.")
        return True

    for index, file_path in enumerate(game_files):
        if stop_signal.is_set():
            return False

        raw_name = os.path.basename(file_path)
        display_name = raw_name if len(raw_name) < 38 else raw_name[:35] + "..."
        percentage = int((index / total_games) * 100)

        progress_hook(percentage, f"Verificando: {display_name}")

        serial = extract_game_serial(file_path)
        if serial:
            target_path = os.path.join(covers_dir, f"{serial}.{extension}")
            if not os.path.exists(target_path):
                progress_hook(percentage, f"Baixando capa: {serial}")
                target_url = URL_MAP[cover_style].format(serial=serial)
                try:
                    urllib.request.urlretrieve(target_url, target_path)
                except urllib.error.URLError:
                    pass

    progress_hook(100, "Tudo pronto! Iniciando emulador...")
    return True


def execute_emulator_binary(config: Dict[str, str]) -> None:
    command_string = config["executavel_pcsx2"]
    try:
        if os.name != 'posix' and os.path.exists(command_string):
            subprocess.Popen([command_string])
        else:
            parsed_arguments = shlex.split(command_string)
            subprocess.Popen(parsed_arguments)
    except (subprocess.SubprocessError, FileNotFoundError) as error:
        messagebox.showerror("Erro", f"Não foi possível iniciar o PCSX2:\n{error}")


def apply_window_icon(window: tk.Tk) -> None:
    clean_b64 = LOGO_B64.strip()
    if not clean_b64 or clean_b64.startswith("COLE_O_SEU"):
        return
        
    try:
        image_data = base64.b64decode(clean_b64)
        pil_image = Image.open(io.BytesIO(image_data))
        pil_image = pil_image.resize((64, 64), getattr(Image, 'Resampling', Image).LANCZOS)
        photo_image = ImageTk.PhotoImage(pil_image)
        window.iconphoto(True, photo_image)
        window.icon_reference = photo_image
    except Exception:
        pass


def render_in_app_logo(parent: tk.Frame) -> None:
    clean_b64 = LOGO_B64.strip()
    if not clean_b64 or clean_b64.startswith("COLE_O_SEU"):
        return
        
    try:
        # Plano A: Renderização perfeita com Pillow
        image_data = base64.b64decode(clean_b64)
        pil_image = Image.open(io.BytesIO(image_data))
        pil_image = pil_image.resize((48, 48), getattr(Image, 'Resampling', Image).LANCZOS)
        photo_image = ImageTk.PhotoImage(pil_image)
    except Exception as erro_pillow:
        try:
            # Plano B à prova do PyInstaller: Renderização Nativa Tcl/Tk
            photo_image = tk.PhotoImage(data=clean_b64)
            # Reduz forçadamente caso a imagem original seja muito grande
            photo_image = photo_image.subsample(8, 8)
        except Exception as erro_tk:
            # O PROGRAMA GRITA O ERRO SE AS DUAS FORMAS FALHAREM!
            messagebox.showerror("Erro de Compilação", f"PyInstaller falhou nas bibliotecas.\n\nDetalhe Pillow:\n{erro_pillow}\n\nDetalhe Tkinter:\n{erro_tk}")
            return
            
    logo_label = tk.Label(parent, image=photo_image, bg=COLOR_BG_MAIN, borderwidth=0)
    logo_label.image = photo_image
    logo_label.pack(side="left", padx=(0, 15))


class AppConfig(tk.Tk):
    def __init__(self, active_config: Optional[Dict[str, str]] = None):
        super().__init__()
        self.title("PCSX2 CoverSync")
        self.geometry("620x560")
        self.configure(bg=COLOR_BG_MAIN)
        self.resizable(False, False)

        apply_window_icon(self)

        self.var_games = tk.StringVar()
        self.var_covers = tk.StringVar()
        self.var_exec = tk.StringVar()
        self.var_style = tk.StringVar(value="3d")

        if active_config:
            self.var_games.set(active_config.get("pasta_jogos", ""))
            self.var_covers.set(active_config.get("pasta_covers", ""))
            self.var_exec.set(active_config.get("executavel_pcsx2", ""))
            self.var_style.set(active_config.get("tipo_capa", "3d"))
        else:
            discovered_paths = detect_environment_paths()
            self.var_games.set(discovered_paths["games_dir"])
            self.var_covers.set(discovered_paths["covers_dir"])
            self.var_exec.set(discovered_paths["pcsx2_executable"])

        self._build_ui_components()

    def _build_ui_components(self) -> None:
        header_frame = tk.Frame(self, bg=COLOR_BG_MAIN)
        header_frame.pack(fill="x", padx=30, pady=(25, 10))

        render_in_app_logo(header_frame)
        
        text_container = tk.Frame(header_frame, bg=COLOR_BG_MAIN)
        text_container.pack(side="left", anchor="w")

        tk.Label(text_container, text="PCSX2 CoverSync", font=("Sans", 18, "bold"), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MAIN).pack(anchor="w")
        tk.Label(text_container, text="Sincronize as capas e inicie sua biblioteca de jogos.", font=("Sans", 10), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MUTED).pack(anchor="w", pady=(2, 0))

        body_frame = tk.Frame(self, bg=COLOR_BG_MAIN)
        body_frame.pack(fill="both", expand=True, padx=30)

        self._render_card_row(body_frame, "DIRETÓRIO DOS JOGOS (PS2)", self.var_games, self._browse_games_dir)
        self._render_card_row(body_frame, "PASTA DE COVERS DO PCSX2", self.var_covers, self._browse_covers_dir)
        self._render_card_row(body_frame, "EXECUTÁVEL / COMANDO DO EMULADOR", self.var_exec, self._browse_emulator_bin)

        tk.Label(body_frame, text="ESTILO DE CAPAS", font=("Sans", 9, "bold"), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MUTED).pack(anchor="w", pady=(12, 4))

        selector_container = tk.Frame(body_frame, bg=COLOR_BG_MAIN)
        selector_container.pack(fill="x", pady=(0, 10))
        selector_container.columnconfigure(0, weight=1)
        selector_container.columnconfigure(1, weight=1)

        self.card_2d = tk.Frame(selector_container, bg=COLOR_BG_CARD, highlightthickness=1, highlightbackground="#3a3a3a", cursor="hand2")
        self.card_2d.grid(row=0, column=0, padx=(0, 6), sticky="ew")

        self.card_3d = tk.Frame(selector_container, bg=COLOR_BG_CARD, highlightthickness=1, highlightbackground="#3a3a3a", cursor="hand2")
        self.card_3d.grid(row=0, column=1, padx=(6, 0), sticky="ew")

        rb_2d = tk.Radiobutton(self.card_2d, text="PADRÃO 2D (.JPG)", variable=self.var_style, value="default", font=("Sans", 9, "bold"), bg=COLOR_BG_CARD, fg=COLOR_TXT_MAIN, selectcolor=COLOR_BG_INPUT, activebackground=COLOR_BG_CARD, activeforeground=COLOR_TXT_MAIN, command=self._refresh_card_visuals)
        rb_2d.pack(fill="both", expand=True, ipady=16)

        rb_3d = tk.Radiobutton(self.card_3d, text="MODELO 3D (.PNG)", variable=self.var_style, value="3d", font=("Sans", 9, "bold"), bg=COLOR_BG_CARD, fg=COLOR_TXT_MAIN, selectcolor=COLOR_BG_INPUT, activebackground=COLOR_BG_CARD, activeforeground=COLOR_TXT_MAIN, command=self._refresh_card_visuals)
        rb_3d.pack(fill="both", expand=True, ipady=16)

        self.card_2d.bind("<Button-1>", lambda e: [self.var_style.set("default"), self._refresh_card_visuals()])
        self.card_3d.bind("<Button-1>", lambda e: [self.var_style.set("3d"), self._refresh_card_visuals()])

        self._refresh_card_visuals()

        button_container = tk.Frame(self, bg=COLOR_BG_MAIN)
        button_container.pack(fill="x", side="bottom", padx=30, pady=(10, 25))

        btn_save = tk.Button(
            button_container,
            text="Salvar Modificações",
            font=("Sans", 11, "bold"),
            bg=COLOR_ACCENT_GREEN,
            fg=COLOR_TXT_MAIN,
            bd=0,
            activebackground="#1f8453",
            activeforeground=COLOR_TXT_MAIN,
            cursor="hand2",
            command=self._commit_settings
        )
        btn_save.pack(fill="both", expand=True, ipady=10)

    def _render_card_row(self, parent: tk.Frame, label_text: str, binding_var: tk.StringVar, command_reference: Callable) -> None:
        tk.Label(parent, text=label_text, font=("Sans", 9, "bold"), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MUTED).pack(anchor="w", pady=(10, 2))

        card = tk.Frame(parent, bg=COLOR_BG_CARD, highlightthickness=1, highlightbackground="#3a3a3a")
        card.pack(fill="x", pady=(0, 6))
        card.columnconfigure(0, weight=1)

        entry = tk.Entry(card, textvariable=binding_var, font=("Sans", 10), bg=COLOR_BG_INPUT, fg=COLOR_TXT_MAIN, bd=0, insertbackground=COLOR_TXT_MAIN, highlightthickness=0)
        entry.grid(row=0, column=0, sticky="ew", ipady=8, padx=12, pady=6)

        btn = tk.Button(card, text="Escolher", font=("Sans", 9, "bold"), bg=COLOR_BG_CARD, fg=COLOR_TXT_MAIN, bd=0, activebackground=COLOR_BG_HOVER, activeforeground=COLOR_TXT_MAIN, cursor="hand2", command=command_reference)
        btn.grid(row=0, column=1, sticky="ns", ipadx=18)

        btn.bind("<Enter>", lambda e: btn.config(bg=COLOR_BG_HOVER))
        btn.bind("<Leave>", lambda e: btn.config(bg=COLOR_BG_CARD))

    def _refresh_card_visuals(self) -> None:
        if self.var_style.get() == "default":
            self.card_2d.config(highlightbackground=COLOR_ACCENT_BLUE, highlightthickness=2)
            self.card_3d.config(highlightbackground="#3a3a3a", highlightthickness=1)
        else:
            self.card_3d.config(highlightbackground=COLOR_ACCENT_BLUE, highlightthickness=2)
            self.card_2d.config(highlightbackground="#3a3a3a", highlightthickness=1)

    def _browse_games_dir(self) -> None:
        selected = filedialog.askdirectory()
        if selected:
            self.var_games.set(selected)

    def _browse_covers_dir(self) -> None:
        selected = filedialog.askdirectory()
        if selected:
            self.var_covers.set(selected)

    def _browse_emulator_bin(self) -> None:
        selected = filedialog.askopenfilename(title="Selecione o executável do PCSX2")
        if selected:
            self.var_exec.set(selected)

    def _commit_settings(self) -> None:
        if not self.var_games.get() or not self.var_covers.get() or not self.var_exec.get():
            messagebox.showwarning("Aviso", "Preencha todos os campos do painel.")
            return

        packed_config = {
            "pasta_jogos": self.var_games.get(),
            "pasta_covers": self.var_covers.get(),
            "executavel_pcsx2": self.var_exec.get(),
            "tipo_capa": self.var_style.get()
        }
        save_local_configuration(packed_config)
        self.destroy()
        display_sync_runtime(packed_config)


def display_sync_runtime(config: Dict[str, str]) -> None:
    splash = tk.Tk()
    splash.title("PCSX2 CoverSync")
    splash.geometry("500x170")
    splash.configure(bg=COLOR_BG_MAIN)
    splash.resizable(False, False)

    apply_window_icon(splash)

    execution_interrupt = threading.Event()

    theme_engine = ttk.Style()
    theme_engine.theme_use('clam')
    theme_engine.configure("Gear.Horizontal.TProgressbar", troughcolor=COLOR_BG_CARD, background=COLOR_ACCENT_BLUE, thickness=6, borderwidth=0)

    def trigger_abort_routine():
        execution_interrupt.set()
        if splash.winfo_exists():
            splash.destroy()
        settings_dashboard = AppConfig(active_config=config)
        settings_dashboard.mainloop()

    header_frame = tk.Frame(splash, bg=COLOR_BG_MAIN)
    header_frame.pack(fill="x", padx=30, pady=(25, 0))
    
    render_in_app_logo(header_frame)
    
    text_container = tk.Frame(header_frame, bg=COLOR_BG_MAIN)
    text_container.pack(side="left", anchor="w")
    
    tk.Label(text_container, text="PCSX2 CoverSync", font=("Sans", 14, "bold"), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MAIN).pack(anchor="w")
    label_status = tk.Label(text_container, text="Iniciando automático...", font=("Sans", 10), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MUTED, anchor="w", justify="left")
    label_status.pack(anchor="w", pady=(2, 0))

    btn_settings = tk.Button(splash, text="⚙️ Ajustes", font=("Sans", 9, "bold"), bg=COLOR_BG_CARD, fg=COLOR_TXT_MAIN, bd=0, activebackground=COLOR_BG_HOVER, activeforeground=COLOR_TXT_MAIN, cursor="hand2", command=trigger_abort_routine)
    btn_settings.place(x=385, y=25, width=85, height=28)

    progress_bar = ttk.Progressbar(splash, style="Gear.Horizontal.TProgressbar", mode="determinate", length=440)
    progress_bar.pack(padx=30, pady=(25, 6))

    label_percentage = tk.Label(splash, text="0%", font=("Sans", 9, "bold"), bg=COLOR_BG_MAIN, fg=COLOR_TXT_MUTED)
    label_percentage.pack(anchor="e", padx=30, pady=(0, 0))

    def gui_refresh_bridge(progress_value: int, prompt_text: str) -> None:
        if not execution_interrupt.is_set() and splash.winfo_exists():
            splash.after(0, lambda: [
                progress_bar.config(value=progress_value) if splash.winfo_exists() else None,
                label_status.config(text=prompt_text) if splash.winfo_exists() else None,
                label_percentage.config(text=f"{progress_value}%") if splash.winfo_exists() else None
            ])

    def runtime_execution_track():
        is_successful = synchronize_assets(config, gui_refresh_bridge, execution_interrupt)
        if is_successful and not execution_interrupt.is_set():
            time.sleep(0.4)
            if splash.winfo_exists():
                splash.after(0, lambda: [
                    splash.destroy() if splash.winfo_exists() else None,
                    execute_emulator_binary(config)
                ])

    threading.Thread(target=runtime_execution_track, daemon=True).start()
    splash.mainloop()


if __name__ == "__main__":
    active_runtime_configuration = load_local_configuration()
    if not active_runtime_configuration:
        initial_setup_app = AppConfig()
        initial_setup_app.mainloop()
    else:
        display_sync_runtime(active_runtime_configuration)